 * Line-level diff of a document against a base, driving a merge.
 */

/**
 * Compute the changes needed to turn `base` into `side`, using a longest
 * common subsequence over whole lines. Ties in subsequence length are
 * broken by preferring the earliest matches: walking both documents from
 * the start, advancing the side whose remaining subsequence is at least as
 * long as the other's, preferring to advance the base when they tie.
 *
 * Returns a list of changes ordered by base position, each replacing the
 * base lines in `[baseStart, baseEnd)` with the side lines in
 * `[sideStart, sideEnd)`. An insertion has `baseStart === baseEnd`; a
 * deletion has `sideStart === sideEnd`.
 */
export function computeChanges(base, side, label) {
  const n = base.length
  const m = side.length

  // dp[i][j] holds the LCS length of base[i:] and side[j:].
  const dp = []
  for (let i = 0; i <= n; i++) dp.push(new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    const dpi = dp[i]
    const dpi1 = dp[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      dpi[j] = base[i] === side[j] ? dpi1[j + 1] + 1 : Math.max(dpi1[j], dpi[j + 1])
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let lastI = 0
  let lastJ = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      if (i > lastI || j > lastJ) {
        changes.push({ side: label, baseStart: lastI, baseEnd: i, sideStart: lastJ, sideEnd: j })
      }
      i++
      j++
      lastI = i
      lastJ = j
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  if (lastI < n || lastJ < m) {
    changes.push({ side: label, baseStart: lastI, baseEnd: n, sideStart: lastJ, sideEnd: m })
  }
  return changes
}
"}

