{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260921T233347Z/cell-mJ0K4G/src/merge.js","content":"/**
 * Building and resolving the regions of a three-way merge.
 */

import { computeChanges } from './diff.js'

function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

// A side that made no change of its own within the region matches the base
// exactly across the region's whole span, so its lines are the base's.
// Otherwise the side's span runs from the smallest start of its own
// changes, moved back by however far the region begins before them, to the
// largest end of its own changes, moved forward by however far the region
// ends after them.
function extractSide(region, side, sourceDoc, base) {
  const own = region.changes.filter(change => change.side === side)
  if (own.length === 0) return base.slice(region.baseStart, region.baseEnd)

  const minBaseStart = Math.min(...own.map(change => change.baseStart))
  const maxBaseEnd = Math.max(...own.map(change => change.baseEnd))
  const sideStart = Math.min(...own.map(change => change.sideStart)) - (minBaseStart - region.baseStart)
  const sideEnd = Math.max(...own.map(change => change.sideEnd)) + (region.baseEnd - maxBaseEnd)
  return sourceDoc.slice(sideStart, sideEnd)
}

function resolveRegion(region, mine, base, theirs) {
  if (region.changes.length === 1) {
    const change = region.changes[0]
    const doc = change.side === 'mine' ? mine : theirs
    return { kind: change.side, lines: doc.slice(change.sideStart, change.sideEnd) }
  }

  const mineLines = extractSide(region, 'mine', mine, base)
  const theirsLines = extractSide(region, 'theirs', theirs, base)
  const baseLines = base.slice(region.baseStart, region.baseEnd)

  if (linesEqual(mineLines, theirsLines)) return { kind: 'both', lines: mineLines }
  if (linesEqual(mineLines, baseLines)) return { kind: 'theirs', lines: theirsLines }
  if (linesEqual(theirsLines, baseLines)) return { kind: 'mine', lines: mineLines }
  return { kind: 'conflict', mineLines, baseLines, theirsLines }
}

/**
 * Split the merge of `mine` and `theirs` against `base` into an ordered
 * list of segments covering every base line: `{ kind: 'stable', lines }`
 * for base lines no change touches, `{ kind: 'mine' | 'theirs' | 'both',
 * lines }` for a region that resolves cleanly, and
 * `{ kind: 'conflict', mineLines, baseLines, theirsLines }` for one that
 * does not.
 */
export function buildSegments(mine, base, theirs) {
  const changes = [...computeChanges(base, mine, 'mine'), ...computeChanges(base, theirs, 'theirs')]
  changes.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    return a.side === b.side ? 0 : a.side === 'mine' ? -1 : 1
  })

  const regions = []
  for (const change of changes) {
    const last = regions[regions.length - 1]
    if (last && change.baseStart <= last.baseEnd) {
      last.baseEnd = Math.max(last.baseEnd, change.baseEnd)
      last.changes.push(change)
    } else {
      regions.push({ baseStart: change.baseStart, baseEnd: change.baseEnd, changes: [change] })
    }
  }

  const segments = []
  let cursor = 0
  for (const region of regions) {
    if (region.baseStart > cursor) segments.push({ kind: 'stable', lines: base.slice(cursor, region.baseStart) })
    segments.push(resolveRegion(region, mine, base, theirs))
    cursor = region.baseEnd
  }
  if (cursor < base.length) segments.push({ kind: 'stable', lines: base.slice(cursor, base.length) })

  return segments
}
"}

